-- Repeatable migration: seed data for local development.
--
-- Generated from database/seed/generate_seed.py against Logan PL.xlsx.
-- Re-run that script after editing the spreadsheet to refresh this file.
--
-- Idempotency model:
--   Every row uses a deterministic UUID derived from uuid5() of a stable key,
--   and every insert ends in `on conflict (id) do nothing`. Re-running this
--   migration on a populated DB is a no-op; missing rows are filled in.
--   For a destructive refresh (e.g. after restructuring the spreadsheet),
--   wipe the data volume with `docker compose down -v` so Flyway's
--   `clean migrate` reapplies everything from scratch.
--
-- Flyway wraps each migration in its own transaction; no explicit begin/commit needed.

set search_path to fitlytics, public;

-- 1. Owner user
--
-- Synthetic dev owner. users.ResolveOrProvision upserts on workos_user_id, so
-- this row is the local mirror the seeded program hangs off. The workos_user_id
-- and email are deliberately fake — never commit a real identity. To drive the
-- UI in dev, point AUTH_BYPASS_USER_ID at this id (bypasses WorkOS), or override
-- workos_user_id locally to bind a real account outside source control.
on conflict (id) do nothing;

-- 2. Canonical exercises referenced by the program.
on conflict (id) do nothing;

-- 3. Program
on conflict (id) do nothing;

-- 3b. Training blocks (mesocycles grouping the weeks)
on conflict (id) do nothing;

-- 4. Weeks (global sequence; deloads at wk 9 & 14)
on conflict (id) do nothing;

-- 5. Days (7 per week; rest days flagged)
on conflict (id) do nothing;

-- 6. Program exercises
on conflict (id) do nothing;

-- 7. Program set groups
on conflict (id) do nothing;

-- 7b. Program sets
on conflict (id) do nothing;

-- 8. Logged sessions for weeks 1-18 (history). Load Used / Last Set RPE
--    from the sheet; sets with no logged load are marked skipped.
on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;
